#!/bin/sh
# generated by rack:fleet render from infra/rack-switch-fleet/sites/ber1.json
routes=10.10.0.101/32
if ip -4 -o addr show dev enp87s0 2>/dev/null | grep -qF ' 192.168.0.10/'; then
  routes="${routes:+$routes,}192.168.0.14/32,192.168.0.15/32,192.168.0.16/32"
fi
exec tailscale --socket=/run/tailscale/tailscaled.sock set --advertise-routes="$routes"
